class Solution {
    public int[][] buildPyramid(int rows) {
        // Pascal's triangle, each row built from row above
        // Inner tile = sum of two tiles above, edges = 1
        int[][] out = new int[rows][];
        for (int i = 0; i < rows; i++) {
            // jagged array, row i has i + 1 tiles
            out[i] = new int[i + 1];
            // edges 1 (same tile when i = 0)
            out[i][0] = out[i][i] = 1;
            // inner tiles = neighbour pairs above
            for (int j = 1; j < i; j++) out[i][j] = out[i - 1][j - 1] + out[i - 1][j];
        }
        return out;
    }
}

