class Solution {
    public int bestRoute(TreeNode root) {
        // Route has one top node, joining downward paths from its children
        // Route topped at node = val + gain of each child
        // Parent extends one child only, so gain = val + larger child gain
        // Iterative post-order (children before parent), so child gains are ready
        // best route anywhere (not 0, since vals can be negative)
        int best = root.val;
        // gain[node] (best downward path starting at node)
        Map<TreeNode, Integer> gain = new HashMap<>();
        // ready runs parallel to stack, true = children already done
        Deque<TreeNode> stack = new ArrayDeque<>();
        Deque<Boolean> ready = new ArrayDeque<>();
        stack.push(root);
        ready.push(false);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            boolean childrenDone = ready.pop();
            // first visit, so push node back, then children above it
            if (!childrenDone) {
                stack.push(node); ready.push(true);
                if (node.right != null) { stack.push(node.right); ready.push(false); }
                if (node.left != null) { stack.push(node.left); ready.push(false); }
                continue;
            }
            // child gain, or 0 if negative or no child
            int leftGain = node.left != null ? Math.max(0, gain.get(node.left)) : 0;
            int rightGain = node.right != null ? Math.max(0, gain.get(node.right)) : 0;
            // route topped here uses both sides
            best = Math.max(best, node.val + leftGain + rightGain);
            // going up, route continues into one child only
            gain.put(node, node.val + Math.max(leftGain, rightGain));
        }
        return best;
    }
}

