class Solution {
    public int bestRoute(TreeNode root) {
        // Route has one top node, joining downward paths from its children
        // Route topped at node = val + gain of each child
        // Parent extends one child only, so gain = val + larger child gain
        // Plain loops, list parents before children, then walk list backwards
        // order (nodes, every parent before its children)
        List<TreeNode> order = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            order.add(node);
            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }
        // gain[node] (best downward path starting at node)
        Map<TreeNode, Integer> gain = new HashMap<>();
        // not 0, since all vals can be negative
        int best = root.val;
        // backwards, so children are done before parents
        for (int k = order.size() - 1; k >= 0; k--) {
            TreeNode node = order.get(k);
            // child gain counts only if positive
            int leftGain = 0;
            if (node.left != null && gain.get(node.left) > 0) {
                leftGain = gain.get(node.left);
            }
            // same for right child
            int rightGain = 0;
            if (node.right != null && gain.get(node.right) > 0) {
                rightGain = gain.get(node.right);
            }
            // route topped here uses both sides
            int throughHere = node.val + leftGain + rightGain;
            if (throughHere > best) {
                best = throughHere;
            }
            // going up, route continues into one child only
            gain.put(node, node.val + Math.max(leftGain, rightGain));
        }
        return best;
    }
}

